function setup(extra={}) {
 const docs=new Map(Object.entries({'googleUserProfiles/auth':{userId:'u1'},'users/u1':{role:'intern',isActive:true,googleUid:'auth',permissions:{payroll:true}},'clients/c1':{name:'測試客戶'},'payrollClients/config':{clientId:'c1'},'employees/e1':emp,...extra}));let writes=[];
 const ref=p=>({path:p});const snap=p=>({id:p.split('/').pop(),ref:ref(p),exists:docs.has(p),data:()=>docs.get(p)});
 const db={doc:ref,collection:p=>({collection:p,where:(field,op,value)=>({collection:p,field,value})}),runTransaction:async cb=>{const staged=[];let wrote=false;const result=await cb({get:async r=>{assert(!wrote,'Firestore prohibits reads after writes');if(r.collection){const matches=[...docs.keys()].filter(p=>p.startsWith(r.collection+'/')&&p.split('/').length===r.collection.split('/').length+1&&(!r.field||docs.get(p)[r.field]===r.value)).map(snap);return {docs:matches,empty:matches.length===0};}return snap(r.path);},set:(r,v,options)=>{wrote=true;staged.push({path:r.path,value:options?.merge?{...docs.get(r.path),...v}:v});},create:(r,v)=>{wrote=true;assert(!docs.has(r.path),'create must not overwrite');staged.push({path:r.path,value:v});}});for(const w of staged)docs.set(w.path,w.value);writes.push(...staged);return result;}};
 class HttpsError extends Error {constructor(code,message){super(message);this.code=code;}}
 const mod=load('functions/src/payroll.ts',{'firebase-admin/firestore':{getFirestore:()=>db},'firebase-functions/v2/https':{onCall:(_,fn)=>fn,HttpsError},'./payrollDomain.js':d});let n=0;
 const call=(data,auth={uid:'auth'})=>mod.payrollCommand({auth,data:{clientId:'c1',operationId:'op'+(++n),...data}});
 return {docs,call,writes};
}
test('save is idempotent across a network retry and changes no legacy documents',async()=>{const s=setup({'monthlySalaries/old':{clientId:'c1',employeeId:'other',month:'2026-01'}});const body={action:'saveSlip',slip:slip(),expectedRevision:0,operationId:'fixed'};const r=await s.call(body);assert.equal(r.slip.revision,1);await s.call(body);assert.equal(s.docs.get('payrollSlips/s1').revision,1);assert(!s.writes.some(w=>w.path.startsWith('monthlySalaries/')));});
