test('correction and supplement mail is labelled and identity numbers are masked',async()=>{assert.equal(d.slipTitle({kind:'regular',replacesId:''}),'薪資單');assert.equal(d.slipTitle({kind:'regular',replacesId:'x'}),'薪資單（更正）');assert.equal(d.slipTitle({kind:'supplement',replacesId:''}),'薪資單（補發）');assert.equal(d.maskIdNumber('A123456789'),'A12****789');assert.equal(d.maskIdNumber(''),'');assert.equal(d.maskIdNumber('AB1'),'****');assert.equal(d.maskBankAccount('12345678'),'****5678');assert.equal(d.maskBankAccount('123'),'****');
 const e={...carryEmp(),idNumber:'A123456789'};const c=paid(e,'2026-10',{},{id:'c',replacesId:'',employee:{name:'n',email:'a@b.co',empNo:'1',idNumber:'A123456789'}});const s=setup({'employees/e1':e,'payrollSlips/c':c});const r=await s.call({action:'send',id:'c',expectedRevision:1});const mail=s.docs.get('mail/'+r.mailId);assert(mail.message.html.includes('A12****789'));assert(!mail.message.html.includes('A123456789'));assert(!mail.message.subject.includes('更正'));
 const old=septemberOld({month:'2026-10',isEmailSent:true});const l=setup({'employees/e1':e,'monthlySalaries/old':{...old}});const fixed=await l.call({action:'saveLegacySeptember',id:'old',expectedRevision:0,expected:{...old},amounts:{...d.legacyAmounts(old),performanceBonus:1},attendance:d.legacyAttendance(old),reason:'更正',correction:true});assert.equal(fixed.record.legacyCorrected,true);const sent=await l.call({action:'sendLegacySeptember',id:'old',expectedRevision:1});const legacyMail=l.docs.get('mail/'+sent.mailId);assert(legacyMail.message.subject.includes('薪資單（更正）'));assert(legacyMail.message.html.includes('薪資單（更正）'));});
test('old record attendance edits recalculate only the amount they drive',()=>{const e=carryEmp();const old=septemberOld({month:'2026-10',lateDeduction:999,leaveDeduction:888,taxFreeOt:777});const b=d.legacyBasis(old,e);assert.deepEqual({...d.legacyRecalculated(b,{...old,lateHours:60},'lateHours')},{lateDeduction:150});assert.deepEqual(Object.keys(d.legacyRecalculated(b,{...old,sickLeave:8},'sickLeave')),['leaveDeduction']);assert.deepEqual(Object.keys(d.legacyRecalculated(b,{...old,normalOt:2},'normalOt')),['taxFreeOt']);assert.deepEqual({...d.legacyRecalculated(b,{...old,workHours:5},'workHours')},{});assert.deepEqual({...d.legacyRecalculated({...b,employmentType:'part_time',baseSalary:200},{...old,workHours:5},'workHours')},{baseSalary:1000});assert.equal(d.legacyBasis(old,null),null);});

// Audit history, keyboard save and removed dead branch.
test('saving an unchanged confirmed slip keeps its version while a changed one still bumps',async()=>{const e=carryEmp();const s=setup({'employees/e1':e});const first=await s.call({action:'saveSlip',slip:paid(e,'2026-10',{},{id:'k',revision:0,status:'draft'}),expectedRevision:0});assert.equal(first.slip.status,'confirmed');const same=await s.call({action:'saveSlip',slip:first.slip,expectedRevision:1});assert.equal(same.slip.revision,1);assert(!s.docs.has('payrollSlips/k/versions/2'));const changed=await s.call({action:'saveSlip',slip:{...first.slip,note:'改備註'},expectedRevision:1});assert.equal(changed.slip.revision,2);});
test('employee saves record masked field changes that can be read back',async()=>{const e={...carryEmp(),idNumber:'A123456789',bankAccount:'12345678',employmentHistory:[{id:'p1',type:'full_time',startDate:'2025-01-01',endDate:null}]};const s=setup({'employees/e1':e});const next={...e,name:'新名字',idNumber:'B987654321',bankAccount:'87654321',compensationHistory:[{...e.compensationHistory[0],baseSalary:38000}]};await s.call({action:'saveEmployee',employee:next,expected:e,operationId:'op-a'});const entry=s.docs.get('employees/e1/versions/op-a');const text=JSON.stringify(entry.changes);assert(text.includes('新名字'));assert(text.includes('B98****321'));assert(text.includes('****4321'));assert(!text.includes('A123456789'));assert(!text.includes('B987654321'));assert(!text.includes('87654321'));assert(text.includes('36,000'));assert(text.includes('38,000'));assert.equal(entry.actor,'u1');
 const history=await s.call({action:'employeeHistory',id:'e1'});assert.equal(history.history.length,1);
 const stored=s.docs.get('employees/e1');await s.call({action:'saveEmployee',employee:{...stored,id:'e1'},expected:{...stored,id:'e1'},operationId:'op-same'});assert(!s.docs.has('employees/e1/versions/op-same'));
 await s.call({action:'saveEmployee',employee:{...e,id:'brand'},expected:null,operationId:'op-new'});assert.equal(s.docs.get('employees/brand/versions/op-new').changes[0].label,'新增員工');
 const other=setup({'employees/e1':{...e,clientId:'c2'}});await assert.rejects(()=>other.call({action:'employeeHistory',id:'e1'}),/不屬於/);});
test('employee changes cover employment and pay additions, removals and identical masks',()=>{const before={id:'e',idNumber:'A123456789',employmentHistory:[{id:'a',type:'full_time',startDate:'2026-01-01',endDate:null}],compensationHistory:[{id:'c',effectiveDate:'2026-01-01',baseSalary:100,hasLaborIns:true}]};const labels=d.employeeChanges(before,{id:'e',idNumber:'A12XXXX789',employmentHistory:[{id:'a',type:'part_time',startDate:'2026-01-01',endDate:null},{id:'b',type:'full_time',startDate:'2026-03-01',endDate:null}],compensationHistory:[]});const flat=JSON.stringify(labels);assert(flat.includes('（已修改）'));assert(flat.includes('身分'));assert(flat.includes('新增任職'));assert(flat.includes('刪除待遇'));assert.equal(d.employeeChanges(before,before).length,0);assert.equal(d.employeeChanges(null,{name:'n'})[0].to,'n');});

// Overtime follows the meal allowance actually paid that month.
test('overtime and annual-leave pay follow the slip meal allowance, deductions and part-time pay do not',()=>{const s=slip();const hours={...s.attendance,normalOt:10};const food=f=>({...s.amounts,foodAllowance:f});const b={...basis,baseSalary:36000,foodAllowance:3000};assert.equal(d.calculate(b,hours,food(3000)).taxFreeOt,2167);assert.equal(d.calculate(b,hours,food(1000)).taxFreeOt,2056);assert.equal(d.calculate(b,hours,food(0)).taxFreeOt,2000);assert.equal(d.calculate(b,{...s.attendance,annualLeave:8},food(1000)).taxFreeOt,1233);const leave={...s.attendance,personalLeave:8,lateHours:60};assert.equal(d.calculate(b,leave,food(1000)).leaveDeduction,1200);assert.equal(d.calculate(b,leave,food(1000)).lateDeduction,150);const part={...b,employmentType:'part_time',baseSalary:200};assert.equal(d.calculate(part,hours,food(1000)).taxFreeOt,d.calculate(part,hours,food(0)).taxFreeOt);});
test('supplement slips keep the contractual meal allowance as the overtime base',()=>{const s=slip();const b={...basis,baseSalary:36000,foodAllowance:3000};assert.equal(d.calculate(b,{...s.attendance,normalOt:10},{...d.emptyValues(d.amountFields)},'supplement').taxFreeOt,2167);});
test('saving a slip recalculates overtime from the meal allowance entered that month',async()=>{const e=carryEmp();const s=setup({'employees/e1':e});const hours={...d.emptyValues(d.attendanceFields),normalOt:10};const r=await s.call({action:'saveSlip',slip:paid(e,'2026-10',{foodAllowance:1000},{id:'food',revision:0,status:'draft',attendance:hours}),expectedRevision:0});assert.equal(r.slip.amounts.foodAllowance,1000);assert.equal(r.slip.amounts.taxFreeOt,2056);assert.equal(r.slip.basis.foodAllowance,3000);});

// Supplement slips were removed: corrections replace them, and any old one still loads.
test('new supplement slips are refused and corrections still work',async()=>{const s=setup();const first=await s.call({action:'saveSlip',slip:slip(),expectedRevision:0});await assert.rejects(()=>s.call({action:'saveSlip',slip:slip({id:'extra',kind:'supplement',relatedId:'s1',reason:'補發',reviewedMonth:true}),expectedRevision:0}),/補發功能已取消/);const fixed=await s.call({action:'saveSlip',slip:slip({id:'fix',replacesId:'s1',reason:'補獎金',reviewedMonth:true,amounts:{...first.slip.amounts,performanceBonus:5000}}),expectedRevision:0});assert.equal(fixed.slip.status,'confirmed');assert.equal(s.docs.get('payrollSlips/s1').status,'superseded');});
